L["Choose an action and complete the announcement before applying."] = "Elige una acción y completa el anuncio antes de aplicar."
-- en: "The condition ordering controls are arrows and draggable rows in the sidebar of the selected category. In Manage categories, the same controls order the categories themselves."
L["The condition ordering controls are arrows and draggable rows in the sidebar of the selected category. In Manage categories, the same controls order the categories themselves."] = "Los controles de orden de las condiciones son las flechas y las filas arrastrables de la barra lateral de la categoría seleccionada. En Gestionar categorías, los mismos controles ordenan las propias categorías."
-- en: "Apply changes before leaving this page?"
L["Apply changes before leaving this page?"] = "¿Aplicar los cambios antes de salir de esta página?"
-- en: "Apply or discard current settings before opening the custom code editor."
L["Apply or discard current settings before opening the custom code editor."] = "Aplica o descarta los ajustes actuales antes de abrir el editor de código personalizado."
-- en: "Apply item-set changes before binding it to an action bar."
L["Apply item-set changes before binding it to an action bar."] = "Aplica los cambios del conjunto de objetos antes de asignarlo a una barra de acción."
-- en: "Choose a new named copy or replace the selected editable entry. Review the destination before importing."
L["Choose a new named copy or replace the selected editable entry. Review the destination before importing."] = "Elige una copia nueva con nombre o sustituye la entrada editable seleccionada. Revisa el destino antes de importar."
-- en: "Clear"
L["Clear"] = "Limpiar"
-- en: "Confirm the Lua import, then review it before saving."
L["Confirm the Lua import, then review it before saving."] = "Confirma la importación de Lua y revísala antes de guardar."
-- en: "IMPORTED_CONDITION"
L["IMPORTED_CONDITION"] = "IMPORTED_CONDITION"
-- en: "Import comparison"
L["Import comparison"] = "Comparación de importación"
-- en: "Imported announcement"
L["Imported announcement"] = "Anuncio importado"
-- en: "Imported category"
L["Imported category"] = "Categoría importada"
-- en: "Imported effect"
L["Imported effect"] = "Efecto importado"
-- en: "Imported profile"
L["Imported profile"] = "Perfil importado"
-- en: "Invalid custom condition."
L["Invalid custom condition."] = "Condición personalizada no válida."
-- en: "Name not supplied"
L["Name not supplied"] = "No se ha indicado ningún nombre"
-- en: "Original name"
L["Original name"] = "Nombre original"
-- en: "Ready to import. Choose replacement or a named copy."
L["Ready to import. Choose replacement or a named copy."] = "Listo para importar. Elige sustituir o una copia con nombre."
-- en: "Replace selected entry"
L["Replace selected entry"] = "Sustituir la entrada seleccionada"
-- en: "That condition identifier already exists."
L["That condition identifier already exists."] = "Ese identificador de condición ya existe."
-- en: "The selected profile changed. Reopen the import window."
L["The selected profile changed. Reopen the import window."] = "El perfil seleccionado ha cambiado. Vuelve a abrir la ventana de importación."
-- en: "This import contains Lua code. Only continue if you trust its author. Import opens the code for review; saving the condition can execute it."
L["This import contains Lua code. Only continue if you trust its author. Import opens the code for review; saving the condition can execute it."] = "Esta importación contiene código Lua. Continúa solo si confías en su autor. Importar abre el código para que lo revises; guardar la condición puede ejecutarlo."
-- en: "Use letters, numbers and underscores for the condition identifier."
L["Use letters, numbers and underscores for the condition identifier."] = "Usa letras, números y guiones bajos para el identificador de la condición."
-- en: "Check %s: %s"
L["Check %s: %s"] = "Comprobar %s: %s"
-- en: "Check syntax"
L["Check syntax"] = "Comprobar sintaxis"
-- en: "Choose icon"
L["Choose icon"] = "Elegir icono"
-- en: "Custom Lua has the same access as the addon. Only import code you trust. Syntax validation cannot establish that a callback is safe or correct. Existing custom widget callbacks still use their original UI contract."
L["Custom Lua has the same access as the addon. Only import code you trust. Syntax validation cannot establish that a callback is safe or correct. Existing custom widget callbacks still use their original UI contract."] = "El Lua personalizado tiene el mismo acceso que el addon. Importa solo código en el que confíes. La validación de sintaxis no puede garantizar que un callback sea seguro o correcto. Los callbacks de widget personalizados existentes siguen usando su contrato de interfaz original."
-- en: "Declare named fields, primitive types, nested records and unions. Example: { spell = { string, number }, unit = string, tests = condition[] }. Schema text is parsed as data and never evaluated as Lua."
L["Declare named fields, primitive types, nested records and unions. Example: { spell = { string, number }, unit = string, tests = condition[] }. Schema text is parsed as data and never evaluated as Lua."] = "Declara campos con nombre, tipos primitivos, registros anidados y uniones. Ejemplo: { spell = { string, number }, unit = string, tests = condition[] }. El texto del esquema se analiza como datos y nunca se evalúa como Lua."
-- en: "Definition"
L["Definition"] = "Definición"
-- en: "Editing code"
L["Editing code"] = "Edición de código"
-- en: "Evaluate"
L["Evaluate"] = "Evaluar"
-- en: "Field schema"
L["Field schema"] = "Esquema de campos"
-- en: "Fields UI"
L["Fields UI"] = "Interfaz de campos"
-- en: "Function tabs edit separate callbacks. Changes stay in a draft. Check syntax compiles every callback without running it. Apply registers the callbacks and can run registration code. Cancel discards the draft. Undo and Redo work across function tabs."
L["Function tabs edit separate callbacks. Changes stay in a draft. Check syntax compiles every callback without running it. Apply registers the callbacks and can run registration code. Cancel discards the draft. Undo and Redo work across function tabs."] = "Las pestañas de funciones editan callbacks separados. Los cambios se quedan en un borrador. Comprobar sintaxis compila todos los callbacks sin ejecutarlos. Aplicar registra los callbacks y puede ejecutar código de registro. Cancelar descarta el borrador. Deshacer y Rehacer funcionan en todas las pestañas de funciones."
-- en: "On register"
L["On register"] = "Al registrar"
-- en: "On unregister"
L["On unregister"] = "Al anular el registro"
-- en: "Summary"
L["Summary"] = "Resumen"
-- en: "Syntax checked. No custom code was executed."
L["Syntax checked. No custom code was executed."] = "Sintaxis comprobada. No se ha ejecutado ningún código personalizado."
-- en: "The custom condition changed elsewhere. Reopen it before saving."
L["The custom condition changed elsewhere. Reopen it before saving."] = "La condición personalizada ha cambiado en otro lugar. Vuelve a abrirla antes de guardar."
-- en: "Trusted code"
L["Trusted code"] = "Código de confianza"
-- en: "Validate"
L["Validate"] = "Validar"
-- en: "All tags"
L["All tags"] = "Todas las etiquetas"
-- en: "Edit the description, tags, author, realm, email, website and version. Source citations remain separate from your attribution. Use changes updates the rotation draft; Apply the rotation to save it. Cancel or Escape restores this dialog’s opening values."
L["Edit the description, tags, author, realm, email, website and version. Source citations remain separate from your attribution. Use changes updates the rotation draft; Apply the rotation to save it. Cancel or Escape restores this dialog’s opening values."] = "Edita la descripción, las etiquetas, el autor, el reino, el correo electrónico, el sitio web y la versión. Las citas de fuentes se mantienen separadas de tu autoría. Usar cambios actualiza el borrador de la rotación; aplica la rotación para guardarla. Cancelar o Esc restaura los valores que tenía este diálogo al abrirse."
-- en: "Invalid tags. Use up to 64 tags of 64 characters, separated by commas."
L["Invalid tags. Use up to 64 tags of 64 characters, separated by commas."] = "Etiquetas no válidas. Usa hasta 64 etiquetas de 64 caracteres, separadas por comas."
-- en: "Separate tags with commas. Use quotes for tags containing commas. Any personal label is allowed."
L["Separate tags with commas. Use quotes for tags containing commas. Any personal label is allowed."] = "Separa las etiquetas con comas. Usa comillas para las etiquetas que contengan comas. Se permite cualquier etiqueta personal."
-- en: "Tags"
L["Tags"] = "Etiquetas"
-- en: "Switch priority"
L["Switch priority"] = "Prioridad de cambio"
-- en: "Priority %d"
L["Priority %d"] = "Prioridad %d"
-- en: "Invalid priority"
L["Invalid priority"] = "Prioridad no válida"
-- en: "Switch priority must be a whole number between -100000 and 100000."
L["Switch priority must be a whole number between -100000 and 100000."] = "La prioridad de cambio debe ser un número entero entre -100000 y 100000."
-- en: "Edit the description, tags, switch priority, author, realm, email, website and version. Source citations remain separate from your attribution. Use changes updates the rotation draft; Apply the rotation to save it. Cancel or Escape restores this dialog’s opening values."
L["Edit the description, tags, switch priority, author, realm, email, website and version. Source citations remain separate from your attribution. Use changes updates the rotation draft; Apply the rotation to save it. Cancel or Escape restores this dialog’s opening values."] = "Edita la descripción, las etiquetas, la prioridad de cambio, el autor, el reino, el correo electrónico, el sitio web y la versión. Las citas de fuentes se mantienen separadas de tu autoría. Usar cambios actualiza el borrador de la rotación; aplica la rotación para guardarla. Cancelar o Esc restaura los valores que tenía este diálogo al abrirse."
-- en: "Higher priority wins within custom or Built In rotations. Custom rotations and a valid saved fallback take precedence over Built In rotations. Equal priorities use name, then identity. Blank means zero."
L["Higher priority wins within custom or Built In rotations. Custom rotations and a valid saved fallback take precedence over Built In rotations. Equal priorities use name, then identity. Blank means zero."] = "La prioridad más alta gana entre las rotaciones personalizadas o entre las integradas. Las rotaciones personalizadas y una rotación de reserva guardada válida tienen preferencia sobre las integradas. Con prioridades iguales se usa el nombre y luego la identidad. En blanco significa cero."
-- en: "Invalid switch priority for %s:%s; explicit repair resets it to zero."
L["Invalid switch priority for %s:%s; explicit repair resets it to zero."] = "Prioridad de cambio no válida en %s:%s; una reparación explícita la restablece a cero."
-- en: "Match all ranks"
L["Match all ranks"] = "Coincidir con todos los rangos"
-- en: "%s (any rank)"
L["%s (any rank)"] = "%s (cualquier rango)"
-- en: "For a numeric spell selection, also recognize auras with the same readable localized spell name. Exact IDs remain the default. Spell names already match by name. Unavailable metadata or restricted aura identity stays unavailable, including under NOT. Different spells sharing a name can match; use exact IDs when that distinction matters."
L["For a numeric spell selection, also recognize auras with the same readable localized spell name. Exact IDs remain the default. Spell names already match by name. Unavailable metadata or restricted aura identity stays unavailable, including under NOT. Different spells sharing a name can match; use exact IDs when that distinction matters."] = "Para una selección de hechizo numérica, reconoce también las auras con el mismo nombre de hechizo localizado legible. Los ID exactos siguen siendo la opción predeterminada. Los nombres de hechizo ya coinciden por nombre. Los metadatos no disponibles o la identidad de aura restringida siguen sin estar disponibles, también bajo NO. Hechizos distintos con el mismo nombre pueden coincidir; usa ID exactos cuando esa distinción importe."
-- en: "Talent tree %s"
L["Talent tree %s"] = "Árbol de talentos %s"
-- en: "This client does not expose a Classic talent-tree layout. The saved tree reference is preserved."
L["This client does not expose a Classic talent-tree layout. The saved tree reference is preserved."] = "Este cliente no expone una disposición de árbol de talentos de Classic. La referencia al árbol guardada se conserva."
-- en: "Talent tree"
L["Talent tree"] = "Árbol de talentos"
-- en: "Talent Tree Points"
L["Talent Tree Points"] = "Puntos del árbol de talentos"
-- en: "points spent in %s"
L["points spent in %s"] = "puntos gastados en %s"
-- en: "Talent tree selects the Classic tree whose spent points are compared. Public points are read again on the next evaluation; missing or restricted points are unavailable, including under NOT. Grids and trait trees are unsupported."
L["Talent tree selects the Classic tree whose spent points are compared. Public points are read again on the next evaluation; missing or restricted points are unavailable, including under NOT. Grids and trait trees are unsupported."] = "Árbol de talentos selecciona el árbol de Classic cuyos puntos gastados se comparan. Los puntos públicos se vuelven a leer en la siguiente evaluación; los puntos que faltan o están restringidos no están disponibles, también bajo NO. Las cuadrículas y los árboles de rasgos no son compatibles."
-- en: "Compare whole points spent from zero to 512. An explicit comparison with zero can describe an unspent tree."
L["Compare whole points spent from zero to 512. An explicit comparison with zero can describe an unspent tree."] = "Compara puntos gastados enteros de cero a 512. Una comparación explícita con cero puede describir un árbol sin puntos gastados."
-- en: "Primary Talent Tree"
L["Primary Talent Tree"] = "Árbol de talentos principal"
-- en: "your primary talent tree is %s"
L["your primary talent tree is %s"] = "tu árbol de talentos principal es %s"
-- en: "Talent tree selects the unique Classic tree with the most positive spent points. Equal maxima, no spent points, missing records and restricted points are unavailable, including under NOT."
L["Talent tree selects the unique Classic tree with the most positive spent points. Equal maxima, no spent points, missing records and restricted points are unavailable, including under NOT."] = "Árbol de talentos selecciona el único árbol de Classic con más puntos gastados, siempre que sean positivos. Los máximos empatados, la ausencia de puntos gastados, los registros que faltan y los puntos restringidos no están disponibles, también bajo NO."
-- en: "The primary tree is derived from readable points, not the saved rotation slot. Hybrid builds may need tree-point or individual-talent conditions instead; the primary tree does not assign a tank or healer role. Grids and trait trees are unsupported."
L["The primary tree is derived from readable points, not the saved rotation slot. Hybrid builds may need tree-point or individual-talent conditions instead; the primary tree does not assign a tank or healer role. Grids and trait trees are unsupported."] = "El árbol principal se deduce de los puntos legibles, no de la casilla de rotación guardada. Las configuraciones híbridas pueden necesitar en su lugar condiciones de puntos del árbol o de talentos concretos; el árbol principal no asigna un rol de tanque o sanador. Las cuadrículas y los árboles de rasgos no son compatibles."
-- en: "Item sets are checked in priority order. Bag counts use the first carried candidate, not the sum. Availability, range and cooldown checks use the first carried or equipped candidate. Missing or restricted observations stay unavailable, including under NOT."
L["Item sets are checked in priority order. Bag counts use the first carried candidate, not the sum. Availability, range and cooldown checks use the first carried or equipped candidate. Missing or restricted observations stay unavailable, including under NOT."] = "Los conjuntos de objetos se comprueban en orden de prioridad. Los recuentos de bolsas usan el primer candidato que llevas, no la suma. Las comprobaciones de disponibilidad, alcance y tiempo de reutilización usan el primer candidato que llevas o tienes equipado. Las observaciones que faltan o están restringidas siguen sin estar disponibles, también bajo NO."
-- en: "Item Available checks the required level and enabled item cooldown. An active cooldown qualifies only when it ends with the readable global cooldown. This condition does not bypass the action's implicit ownership, usability and range checks."
L["Item Available checks the required level and enabled item cooldown. An active cooldown qualifies only when it ends with the readable global cooldown. This condition does not bypass the action's implicit ownership, usability and range checks."] = "Objeto disponible comprueba el nivel requerido y el tiempo de reutilización activo del objeto. Un tiempo de reutilización en curso solo cuenta si termina con el tiempo de reutilización global legible. Esta condición no omite las comprobaciones implícitas de posesión, usabilidad y alcance de la acción."
-- en: "Diagram view"
L["Diagram view"] = "Vista de diagrama"
-- en: "List view"
L["List view"] = "Vista de lista"
-- en: "Switch between the diagram and compact tree list. This changes only the view."
L["Switch between the diagram and compact tree list. This changes only the view."] = "Alterna entre el diagrama y la lista compacta en árbol. Solo cambia la vista."
-- en: "Zoom out"
L["Zoom out"] = "Alejar"
-- en: "Zoom in"
L["Zoom in"] = "Acercar"
-- en: "Reset canvas zoom to 100%. Drag empty canvas space to pan. Window scale is unchanged."
L["Reset canvas zoom to 100%. Drag empty canvas space to pan. Window scale is unchanged."] = "Restablece el zoom del lienzo al 100%. Arrastra el espacio vacío del lienzo para desplazarte. La escala de la ventana no cambia."
-- en: "Navigating rotations"
L["Navigating rotations"] = "Navegación por las rotaciones"
-- en: "Diagram / List changes only the rotation view; General settings choose the default. Diagram has floating minus, percentage and plus controls at the bottom right. Scroll to zoom from 25% to 200%; click the percentage or middle-click to reset to 100%. Drag empty diagram space to pan. List uses normal scrollbars with touching cards and boxed branch arms, False before True. Cooldowns use a separate scrolling grid. Dragging cards reorders them in every view. Each workspace currently shows at most 200 cards; the remaining saved cards are preserved."
L["Diagram / List changes only the rotation view; General settings choose the default. Diagram has floating minus, percentage and plus controls at the bottom right. Scroll to zoom from 25% to 200%; click the percentage or middle-click to reset to 100%. Drag empty diagram space to pan. List uses normal scrollbars with touching cards and boxed branch arms, False before True. Cooldowns use a separate scrolling grid. Dragging cards reorders them in every view. Each workspace currently shows at most 200 cards; the remaining saved cards are preserved."] = "Diagrama / Lista solo cambia la vista de la rotación; los ajustes generales eligen la predeterminada. El diagrama tiene controles flotantes de menos, porcentaje y más abajo a la derecha. Usa la rueda para hacer zoom del 25% al 200%; haz clic en el porcentaje o con el botón central para volver al 100%. Arrastra el espacio vacío del diagrama para desplazarte. Lista usa barras de desplazamiento normales con tarjetas contiguas y brazos de rama enmarcados, Falso antes que Verdadero. Los tiempos de reutilización usan una cuadrícula desplazable aparte. Arrastrar tarjetas las reordena en todas las vistas. Cada espacio de trabajo muestra actualmente un máximo de 200 tarjetas; las demás tarjetas guardadas se conservan."
-- en: "Enabled / Disabled"
L["Enabled / Disabled"] = "Activado / Desactivado"
-- en: "Announcement substitutions"
L["Announcement substitutions"] = "Sustituciones de anuncios"
-- en: "New, Duplicate, Import/Export and Compare"
L["New, Duplicate, Import/Export and Compare"] = "Nuevo, Duplicar, Importar/exportar y Comparar"
-- en: "Announcement details stay always expanded while editing. Press Enter or leave a text field to stage its value; Apply saves the draft. Invalid fields must be corrected before Apply; Discard abandons pending changes. Searchable selectors open on click and filter as you type. The page Help icon explains every option and text substitution."
L["Help.Announces.editing"] = "Los detalles del anuncio se mantienen siempre desplegados durante la edición. Pulsa Intro o sal de un campo de texto para preparar su valor; Aplicar guarda el borrador. Los campos no válidos deben corregirse antes de Aplicar; Descartar abandona los cambios pendientes. Los selectores con búsqueda se abren al hacer clic y filtran mientras escribes. El icono de Ayuda de la página explica cada opción y cada sustitución de texto."
-- en: "Announce selected spell casts or item uses independently of your active rotation, or invoke a configured Via Script/Macro entry directly. Select an entry in the sidebar, or use New to prepare one. The trigger applies to every ordered output card; each card has its own destination and conditions. These settings do not cast spells or use items. Cast-triggered announcements follow RM's combat-data policy and do not run on reference-only clients."
L["Help.Announces.overview"] = "Anuncia los lanzamientos de hechizos o usos de objetos seleccionados independientemente de tu rotación activa, o invoca directamente una entrada configurada Mediante script/macro. Selecciona una entrada en la barra lateral o usa Nuevo para preparar una. El activador se aplica a cada tarjeta de salida ordenada; cada tarjeta tiene su propio destino y sus propias condiciones. Estos ajustes no lanzan hechizos ni usan objetos. Los anuncios activados por lanzamientos siguen la política de datos de combate de RM y no se ejecutan en clientes solo de referencia."
-- en: "An optional name identifies this announcement in the sidebar. Without one, the action name or Via Script/Macro identifier is used. Changing this display name does not change the watched action or callable identifier."
L["Help.Announces.name"] = "Un nombre opcional identifica este anuncio en la barra lateral. Si no lo tiene, se usa el nombre de la acción o el identificador Mediante script/macro. Cambiar este nombre visible no cambia la acción vigilada ni el identificador invocable."
-- en: "Choose Spell, Pet Spell, Item or Via Script/Macro. Changing type clears the previous action and exact-rank choice. Via Script/Macro uses an Identifier instead of a cast event or stored action; switching back restores the event selector. Choosing the current type keeps its fields."
L["Help.Announces.type"] = "Elige Hechizo, Hechizo de mascota, Objeto o Mediante script/macro. Cambiar el tipo borra la acción anterior y la opción de rango exacto. Mediante script/macro usa un Identificador en lugar de un evento de lanzamiento o una acción guardada; al volver a cambiar se restaura el selector de eventos. Elegir el tipo actual conserva sus campos."
-- en: "Watch one of your spells. Choose the spell in the searchable field below Action Type."
L["Help.Announces.type.spell"] = "Vigila uno de tus hechizos. Elige el hechizo en el campo con búsqueda que hay debajo de Tipo de acción."
-- en: "Watch a spell from your pet spellbook. The spell selector uses the pet catalog for this action type."
L["Help.Announces.type.pet"] = "Vigila un hechizo del libro de hechizos de tu mascota. El selector de hechizos usa el catálogo de la mascota para este tipo de acción."
-- en: "Watch item-use spells from a reusable item set or a custom list. This is an announcement trigger; it does not choose an item to use for you."
L["Help.Announces.type.item"] = "Vigila los hechizos de uso de objeto de un conjunto de objetos reutilizable o de una lista personalizada. Es un activador de anuncio; no elige por ti qué objeto usar."
-- en: "Search by spell name, select a result, or drag a spell from your spellbook or action bar into the field. The icon and name identify the selected spell. Spell and pet spell choices keep their respective catalog scope."
L["Help.Announces.spell"] = "Busca por nombre de hechizo, selecciona un resultado o arrastra un hechizo desde tu libro de hechizos o tu barra de acción al campo. El icono y el nombre identifican el hechizo seleccionado. Las opciones de hechizo y de hechizo de mascota conservan el ámbito de su catálogo respectivo."
-- en: "Checked limits matching to the selected rank. Unchecked includes the known ranks in that spell family. This checkbox is shown only for Spell and Pet Spell."
L["Help.Announces.ranked"] = "Si está marcada, limita las coincidencias al rango seleccionado. Si no, incluye los rangos conocidos de esa familia de hechizos. Esta casilla solo se muestra para Hechizo y Hechizo de mascota."
-- en: "Choose a reusable set, or Custom to edit this announcement's own list. For a custom list, search for or drag items into the fields; Add item appends one and a red trash can removes an entry. Any matching item-use spell in the list can trigger the announcement; list order does not limit announcements to the first carried item. Changes to a shared set belong on the Item Sets page."
L["Help.Announces.items"] = "Elige un conjunto reutilizable, o Personalizado para editar la lista propia de este anuncio. En una lista personalizada, busca objetos o arrástralos a los campos; Añadir objeto añade uno al final y la papelera roja quita una entrada. Cualquier hechizo de uso de objeto coincidente de la lista puede activar el anuncio; el orden de la lista no limita los anuncios al primer objeto que lleves. Los cambios en un conjunto compartido se hacen en la página Conjuntos de objetos."
-- en: "For automatic action types, choose which observed cast event triggers this entry. A start, stop, interruption, failure or delay is different from a successful cast. Client support determines which events and observations are available. Via Script/Macro has no cast event."
L["Help.Announces.event"] = "En los tipos de acción automáticos, elige qué evento de lanzamiento observado activa esta entrada. Un inicio, una detención, una interrupción, un fallo o un retraso no son lo mismo que un lanzamiento con éxito. La compatibilidad del cliente determina qué eventos y observaciones están disponibles. Mediante script/macro no tiene evento de lanzamiento."
-- en: "The cast or channel started. This event does not mean it will finish successfully."
L["Help.Announces.event.START"] = "El lanzamiento o la canalización ha empezado. Este evento no significa que vaya a terminar con éxito."
-- en: "The cast or channel stopped. A stop alone does not establish whether it succeeded."
L["Help.Announces.event.STOP"] = "El lanzamiento o la canalización se ha detenido. Una detención por sí sola no indica si tuvo éxito."
-- en: "The client reported a successful spell cast or item-use spell. For a channel, this can occur as channeling begins rather than after its final tick."
L["Help.Announces.event.SUCCEEDED"] = "El cliente ha informado de un lanzamiento de hechizo o de un hechizo de uso de objeto con éxito. En una canalización, puede producirse al empezar a canalizar en lugar de tras su último tick."
-- en: "The client reported that the cast was interrupted. This can include cancelling a cast yourself."
L["Help.Announces.event.INTERRUPTED"] = "El cliente ha informado de que el lanzamiento se interrumpió. Esto puede incluir que canceles tú mismo un lanzamiento."
-- en: "The client reported that the cast failed. This is separate from the successful-cast event."
L["Help.Announces.event.FAILED"] = "El cliente ha informado de que el lanzamiento falló. Es distinto del evento de lanzamiento con éxito."
-- en: "The client reported a delay to the cast. This event is not a completion or success notification."
L["Help.Announces.event.DELAYED"] = "El cliente ha informado de un retraso en el lanzamiento. Este evento no es una notificación de finalización ni de éxito."
-- en: "Choose a chat destination, local output, a named Emote or Audible. Emote replaces Text with an emote selector and optional recipient. Audible replaces Text with Sound. Text is retained when switching modes. Say, Yell, Whisper and named joined channels are offered only for Via Script/Macro and remain subject to native restrictions."
L["Help.Announces.announce"] = "Elige un destino de chat, la salida local, una emoción con nombre o Sonoro. Emoción sustituye Texto por un selector de emociones y un destinatario opcional. Sonoro sustituye Texto por Sonido. El texto se conserva al cambiar de modo. Decir, Gritar, Susurrar y los canales con nombre a los que te has unido solo se ofrecen para Mediante script/macro y siguen sujetos a las restricciones nativas."
-- en: "Play the selected sound locally on the Master audio channel; no chat message is sent. Choose an available sound before applying the announcement."
L["Help.Announces.channel.audible"] = "Reproduce el sonido seleccionado localmente en el canal de audio principal; no se envía ningún mensaje de chat. Elige un sonido disponible antes de aplicar el anuncio."
-- en: "Use raid chat while in a raid, party chat while in a party, or your local chat frame while solo."
L["Help.Announces.channel.partyraid"] = "Usa el chat de banda si estás en una banda, el de grupo si estás en un grupo o tu marco de chat local si vas en solitario."
-- en: "Use party chat when grouped, including your party within a raid. This destination produces no solo chat message."
L["Help.Announces.channel.party"] = "Usa el chat de grupo cuando estés agrupado, incluido tu grupo dentro de una banda. Este destino no genera ningún mensaje de chat en solitario."
-- en: "Request group warning output. Depending on group membership and permissions, RM may use raid chat, party chat, or local output instead."
L["Help.Announces.channel.raidwarn"] = "Solicita una alerta de grupo. Según la pertenencia al grupo y los permisos, RM puede usar en su lugar el chat de banda, el de grupo o la salida local."
-- en: "A saved free-text emote keeps its original message. Select Emote to use a named client emote instead."
L["Help.Announces.channel.emote"] = "Una emoción de texto libre guardada conserva su mensaje original. Selecciona Emoción para usar en su lugar una emoción con nombre del cliente."
-- en: "Custom emote"
L["Custom emote"] = "Emoción personalizada"
-- en: "Use spell recipient ({{target}})"
L["Use spell recipient ({{target}})"] = "Usar el destinatario del hechizo ({{target}})"
-- en: "Automatic Say and Yell are unavailable. Choose another announcement destination."
L["Automatic Say and Yell are unavailable. Choose another announcement destination."] = "Decir y Gritar automáticos no están disponibles. Elige otro destino para el anuncio."
-- en: "Choose a named emote from this client's slash commands, such as /cheer. This does not send the Text field as a custom emote."
L["Help.Announces.channel.gesture"] = "Elige una emoción con nombre de los comandos de barra de este cliente, como /cheer. No envía el campo Texto como emoción personalizada."
-- en: "Choose the emote to perform when the configured cast event is observed. The client may restrict an emote or require a hardware action; RM does not retry through another output path."
L["Help.Announces.emote"] = "Elige la emoción que se realizará cuando se observe el evento de lanzamiento configurado. El cliente puede restringir una emoción o exigir una acción de hardware; RM no lo reintenta por otra vía de salida."
-- en: "For cast entries, checked directs the emote to the recipient recorded for this exact cast, including click casting. It does not use your current target or a previous cast's recipient. For Via Script/Macro, checked uses the supplied macro unit. A missing recipient skips targeted output. Unchecked performs the emote without a target."
L["Help.Announces.emote_target"] = "En las entradas de lanzamiento, si está marcada, dirige la emoción al destinatario registrado para ese lanzamiento exacto, incluido el lanzamiento con clic. No usa tu objetivo actual ni el destinatario de un lanzamiento anterior. En Mediante script/macro, si está marcada, usa la unidad de la macro proporcionada. Si falta el destinatario, se omite la salida dirigida. Si no está marcada, realiza la emoción sin objetivo."
-- en: "Write to your own chat frame. Other players do not receive this message."
L["Help.Announces.channel.local"] = "Escribe en tu propio marco de chat. Los demás jugadores no reciben este mensaje."
-- en: "Enter the message for a chat destination. The substitutions below insert action and cast information when it is available. This text is not used for Audible or named Emote output."
L["Help.Announces.text"] = "Introduce el mensaje para un destino de chat. Las sustituciones de abajo insertan información de la acción y del lanzamiento cuando está disponible. Este texto no se usa en la salida Sonoro ni en la de una emoción con nombre."
-- en: "For cast entries, {{spell}} is a spell link, {{item}} an item link and {{event}} the localized event name. {{target}} uses the recorded cast target, with the last recorded target for that spell as a fallback; it does not automatically use your selected target or your name. Unavailable cast substitutions can remain unchanged. Via Script/Macro instead uses its supplied target and spell, {{event}} becomes Via Script/Macro, and required missing inputs skip output; this API supplies no {{item}}."
L["Help.Announces.substitutions"] = "En las entradas de lanzamiento, {{spell}} es un enlace de hechizo, {{item}} un enlace de objeto y {{event}} el nombre localizado del evento. {{target}} usa el objetivo registrado del lanzamiento y, como alternativa, el último objetivo registrado para ese hechizo; no usa automáticamente tu objetivo seleccionado ni tu nombre. Las sustituciones de lanzamiento no disponibles pueden quedar sin cambios. Mediante script/macro usa en su lugar el objetivo y el hechizo que se le proporcionan, {{event}} pasa a ser Mediante script/macro, y si faltan datos necesarios se omite la salida; esta API no proporciona {{item}}."
-- en: "Choose a sound supplied by the shared-media catalog, then click Play to preview it. Preview is local and does not save the draft. An unavailable sound cannot be previewed; Audible announcements require a nonempty sound selection."
L["Help.Announces.sound"] = "Elige un sonido del catálogo de medios compartidos y haz clic en Reproducir para previsualizarlo. La vista previa es local y no guarda el borrador. Un sonido no disponible no se puede previsualizar; los anuncios sonoros requieren una selección de sonido no vacía."
-- en: "The pill turns this entry on or off while keeping its fields. Disabled entries do not announce matching casts or macro invocations. Apply saves the changed state."
L["Help.Announces.state"] = "La etiqueta activa o desactiva esta entrada conservando sus campos. Las entradas desactivadas no anuncian los lanzamientos ni las invocaciones de macro coincidentes. Aplicar guarda el estado cambiado."
-- en: "Edits stay in a draft until Apply. Complete the action or Via Script/Macro identifier and other required fields before saving. Discard abandons changes to saved announcements; Cancel closes a new creation draft. Leaving pending changes offers Apply, Discard or Cancel navigation."
L["Help.Announces.save"] = "Las ediciones se quedan en un borrador hasta Aplicar. Completa la acción o el identificador Mediante script/macro y los demás campos obligatorios antes de guardar. Descartar abandona los cambios de los anuncios guardados; Cancelar cierra un borrador de creación nuevo. Salir con cambios pendientes ofrece navegar con Aplicar, Descartar o Cancelar."
-- en: "Use the sidebar buttons to create, duplicate, transfer or compare announcements. Apply saves the imported draft; Compare does not merge entries. Via Script/Macro Duplicate assigns a distinct identifier and every copied output gets a fresh identity. Series exports use version 2; version 1 remains available for legacy single-output entries. Imports and Apply reject ambiguous identifiers. The red trash permanently deletes the selected saved entry after confirmation. Resolve pending edits first; deletion does not carry into the next selected draft."
L["Help.Announces.collections"] = "Usa los botones de la barra lateral para crear, duplicar, transferir o comparar anuncios. Aplicar guarda el borrador importado; Comparar no fusiona entradas. Duplicar en Mediante script/macro asigna un identificador distinto y cada salida copiada recibe una identidad nueva. Las exportaciones de series usan la versión 2; la versión 1 sigue disponible para las entradas antiguas de una sola salida. Las importaciones y Aplicar rechazan los identificadores ambiguos. La papelera roja borra permanentemente la entrada guardada seleccionada tras confirmarlo. Resuelve antes las ediciones pendientes; el borrado no se traslada al siguiente borrador seleccionado."
-- en: "Press Enter or leave a text field to stage its value; Apply saves the draft. Invalid text stays red and blocks navigation until corrected. Searchable selectors open on click and filter as you type. Section headings collapse or expand their contents."
L["Press Enter or leave a text field to stage its value; Apply saves the draft. Invalid text stays red and blocks navigation until corrected. Searchable selectors open on click and filter as you type. Section headings collapse or expand their contents."] = "Pulsa Intro o sal de un campo de texto para preparar su valor; Aplicar guarda el borrador. El texto no válido se queda en rojo y bloquea la navegación hasta que se corrija. Los selectores con búsqueda se abren al hacer clic y filtran mientras escribes. Los encabezados de sección pliegan o despliegan su contenido."
-- en: "An item set is an ordered list of alternatives, such as different mana potions. Runtime selection checks the list from the top for a carried or, where requested, equipped item. Priority comes from the order you choose, not the item level. Selecting an item does not by itself prove that it is usable, off cooldown, or in range; action readiness is checked separately."
L["Help.ItemSets.overview"] = "Un conjunto de objetos es una lista ordenada de alternativas, como distintas pociones de maná. La selección en tiempo de ejecución recorre la lista desde arriba buscando un objeto que lleves o, cuando se pide, que tengas equipado. La prioridad la marca el orden que elijas, no el nivel del objeto. Seleccionar un objeto no demuestra por sí solo que se pueda usar, que no esté en tiempo de reutilización o que esté al alcance; la disponibilidad de la acción se comprueba por separado."
-- en: "Name the selected set so it can be found in the sidebar and referenced by rotations or conditions. New opens a name form; its first Apply saves an empty named set. Add items afterward and Apply again to save them. Discarding later item edits keeps that already saved set. Renaming a set does not change its identity in saved references."
L["Help.ItemSets.name"] = "Pon nombre al conjunto seleccionado para encontrarlo en la barra lateral y para que las rotaciones o condiciones puedan hacer referencia a él. Nuevo abre un formulario de nombre; su primer Aplicar guarda un conjunto vacío con nombre. Después, añade objetos y vuelve a Aplicar para guardarlos. Descartar las ediciones de objetos posteriores conserva el conjunto ya guardado. Renombrar un conjunto no cambia su identidad en las referencias guardadas."
-- en: "Checked stores this set in the shared global collection, available to other profiles and characters using this addon database. Unchecked stores it in the current profile, which can itself be shared by characters. This is a staged move; Apply saves it. A profile set takes precedence if a global set has the same saved identity."
L["Help.ItemSets.global"] = "Si está marcada, guarda este conjunto en la colección global compartida, disponible para otros perfiles y personajes que usen esta base de datos del addon. Si no, lo guarda en el perfil actual, que a su vez pueden compartir varios personajes. Es un movimiento preparado; Aplicar lo guarda. Un conjunto de perfil tiene preferencia si un conjunto global tiene la misma identidad guardada."
-- en: "The list of item cards is the priority order. Put preferred items first. RM can leave a selection unavailable when required inventory or identity observations are missing; it does not treat unknown data as proof that a lower-priority item should be used. The sidebar icon represents the first defined item and need not be the currently carried or highlighted one."
L["Help.ItemSets.items"] = "La lista de tarjetas de objeto es el orden de prioridad. Pon primero los objetos preferidos. RM puede dejar una selección como no disponible cuando faltan observaciones necesarias del inventario o de identidad; no trata los datos desconocidos como prueba de que deba usarse un objeto de menor prioridad. El icono de la barra lateral representa el primer objeto definido y no tiene por qué ser el que llevas o el resaltado actualmente."
-- en: "Search by item name and choose a result, or drag an item from your bags or action bar into its field. The icon identifies the item; metadata can take time to load. Edit a row to replace that entry. Use its red trash can to remove it rather than clearing a required item field."
L["Help.ItemSets.item"] = "Busca por nombre de objeto y elige un resultado, o arrastra un objeto desde tus bolsas o tu barra de acción a su campo. El icono identifica el objeto; los metadatos pueden tardar en cargarse. Edita una fila para sustituir esa entrada. Usa su papelera roja para quitarla en lugar de vaciar un campo de objeto obligatorio."
-- en: "Choose or drag an item into the empty item field above the list, then click Add item to append it to the priority list, or drag Add item into a gap between cards to insert it there. Entering an item in this field alone does not add a row."
L["Help.ItemSets.add"] = "Elige o arrastra un objeto al campo de objeto vacío que hay sobre la lista y luego haz clic en Añadir objeto para añadirlo al final de la lista de prioridad, o arrastra Añadir objeto a un hueco entre tarjetas para insertarlo ahí. Introducir un objeto solo en este campo no añade ninguna fila."
-- en: "Move Up / Move Down"
L["Move Up / Move Down"] = "Subir / Bajar"
-- en: "Use the arrows on the left, or drag an item row into a highlighted insertion gap. Ctrl-drag moves that row and all following entries together. The floating preview identifies what you are moving. Moves past the beginning or end are unavailable. Reordering changes priority and stays in the draft until Apply."
L["Help.ItemSets.order"] = "Usa las flechas de la izquierda o arrastra una fila de objeto a un hueco de inserción resaltado. Ctrl+arrastrar mueve esa fila junto con todas las entradas siguientes. La vista previa flotante identifica lo que estás moviendo. Los movimientos más allá del principio o del final no están disponibles. Reordenar cambia la prioridad y se queda en el borrador hasta Aplicar."
-- en: "Bind / Unbind"
L["Bind / Unbind"] = "Asignar / Desasignar"
-- en: "Outside combat, apply pending item-set edits before binding. Drag the set (its row in the list, or the Bind pill) onto any action bar slot; an occupied slot swaps, leaving its previous action on the cursor. Or click Bind and then click an empty slot. Both pick up the first available item of the set. RM records the slot and updates it as item availability changes. The pill shows bound slot numbers; click it to unbind and remove still-matching bar items. Replaced bar actions are preserved. Binding changes are immediate action-bar operations, independent of the draft and its history."
L["Help.ItemSets.binding"] = "Fuera de combate, aplica las ediciones pendientes del conjunto de objetos antes de asignarlo. Arrastra el conjunto (su fila en la lista o la etiqueta Asignar) a cualquier casilla de la barra de acción; una casilla ocupada se intercambia y deja su acción anterior en el cursor. O haz clic en Asignar y luego en una casilla vacía. Ambas opciones toman el primer objeto disponible del conjunto. RM registra la casilla y la actualiza según cambie la disponibilidad de los objetos. La etiqueta muestra los números de las casillas asignadas; haz clic en ella para desasignar y quitar los objetos de la barra que aún coincidan. Las acciones de barra sustituidas se conservan. Los cambios de asignación son operaciones inmediatas sobre la barra de acción, independientes del borrador y de su historial."
-- en: "Restore the packaged item list for this set. Reset is available only for a set with a packaged default. The restored list is staged until Apply; the name is kept."
L["Help.ItemSets.reset"] = "Restaura la lista de objetos incluida para este conjunto. Restablecer solo está disponible para un conjunto con valores predeterminados incluidos. La lista restaurada queda preparada hasta Aplicar; el nombre se conserva."
-- en: "The red trash can at the top right permanently removes the selected saved set after confirmation. Resolve pending edits before the final warning. References in rotations or conditions then need another set. Deletion reconciles still-matching bound bar actions and keeps the set if unbinding fails; the next selection opens without an unsaved deletion marker."
L["Help.ItemSets.delete"] = "La papelera roja de arriba a la derecha elimina permanentemente el conjunto guardado seleccionado tras confirmarlo. Resuelve las ediciones pendientes antes del aviso final. Las referencias en rotaciones o condiciones necesitarán entonces otro conjunto. El borrado concilia las acciones de barra asignadas que aún coinciden y conserva el conjunto si falla la desasignación; la siguiente selección se abre sin marca de borrado sin guardar."
-- en: "Undo / Redo"
L["Undo / Redo"] = "Deshacer / Rehacer"
-- en: "Undo and Redo travel through recent item-set draft edits, including replacements, additions, ordering and row removals. They are unavailable when that direction has no history. Apply, Discard or leaving the page clears this bounded history. They do not reverse confirmed entity deletion or explicit action-bar binding operations."
L["Help.ItemSets.history"] = "Deshacer y Rehacer recorren las ediciones recientes del borrador del conjunto de objetos, incluidas sustituciones, adiciones, ordenaciones y eliminaciones de filas. No están disponibles cuando no hay historial en esa dirección. Aplicar, Descartar o salir de la página borra este historial limitado. No revierten el borrado confirmado de entidades ni las operaciones explícitas de asignación a la barra de acción."
-- en: "Ordinary item-set edits stay in a draft until Apply. Discard restores the saved item sets. Cancel closes a new creation draft. Leaving with pending changes offers Apply, Discard or Cancel navigation. Invalid fields must be corrected before Apply; Discard can abandon them."
L["Help.ItemSets.save"] = "Las ediciones normales del conjunto de objetos se quedan en un borrador hasta Aplicar. Descartar restaura los conjuntos de objetos guardados. Cancelar cierra un borrador de creación nuevo. Salir con cambios pendientes ofrece navegar con Aplicar, Descartar o Cancelar. Los campos no válidos deben corregirse antes de Aplicar; Descartar puede abandonarlos."
-- en: "Use the buttons below the sidebar to create, duplicate, transfer, or compare sets. Duplicate makes an independent profile copy. Import shows the source name and can create a renamed copy or replace the selected list; Apply saves the staged result. Compare inspects differences without merging or modifying either set."
L["Help.ItemSets.collections"] = "Usa los botones de debajo de la barra lateral para crear, duplicar, transferir o comparar conjuntos. Duplicar crea una copia independiente en el perfil. Importar muestra el nombre de origen y puede crear una copia renombrada o sustituir la lista seleccionada; Aplicar guarda el resultado preparado. Comparar examina las diferencias sin fusionar ni modificar ninguno de los conjuntos."
-- en: "Legacy macro buttons"
L["Legacy macro buttons"] = "Botones de macro antiguos"
-- en: "Legacy clients may allow /click to invoke an RM item-set button separately from action-bar binding. The name is RM_ followed by the set name with non-alphanumeric characters removed, then an underscore and unit token. For a set named Bandages, an example is /click [@mouseover,nodead,help] RM_Bandages_mouseover. Other unit suffixes include player, pet, target, focus, pettarget, targettarget, focustarget, and mouseovertarget. These buttons contain item-use macro lines and do not provide the same readiness or first-item guarantee as the recommendation engine. Availability is subject to the client's secure-button and macro restrictions; reference-only support does not promise executable macro buttons."
L["Help.ItemSets.macros"] = "Los clientes antiguos pueden permitir que /click invoque un botón de conjunto de objetos de RM aparte de la asignación a la barra de acción. El nombre es RM_ seguido del nombre del conjunto sin caracteres no alfanuméricos, luego un guion bajo y un token de unidad. Para un conjunto llamado Bandages, un ejemplo es /click [@mouseover,nodead,help] RM_Bandages_mouseover. Otros sufijos de unidad son player, pet, target, focus, pettarget, targettarget, focustarget y mouseovertarget. Estos botones contienen líneas de macro de uso de objetos y no ofrecen la misma garantía de disponibilidad ni de primer objeto que el motor de recomendaciones. La disponibilidad depende de las restricciones de botones seguros y macros del cliente; la compatibilidad solo de referencia no garantiza botones de macro ejecutables."
-- en: "Search for an item or drag it into the item field or icon. Choose the result to retain its exact item identity. The icon and name may be unavailable until metadata loads. Field clearing and save behavior belong to the editor that contains this list; use Delete when you intend to remove an entry."
L["Help.ItemSets.list.item"] = "Busca un objeto o arrástralo al campo o al icono del objeto. Elige el resultado para conservar su identidad exacta. El icono y el nombre pueden no estar disponibles hasta que se carguen los metadatos. Vaciar el campo y el comportamiento al guardar dependen del editor que contiene esta lista; usa Borrar cuando quieras quitar una entrada."
-- en: "Move this entry to the first position in the item priority list, when that control is offered."
L["Help.ItemSets.list.top"] = "Mueve esta entrada a la primera posición de la lista de prioridad de objetos, cuando se ofrezca ese control."
-- en: "Move this entry one position earlier. A move before the first entry is unavailable."
L["Help.ItemSets.list.up"] = "Sube esta entrada una posición. No se puede subir por encima de la primera entrada."
-- en: "Move this entry one position later. A move past the final entry is unavailable."
L["Help.ItemSets.list.down"] = "Baja esta entrada una posición. No se puede bajar por debajo de la última entrada."
-- en: "Move this entry to the final position in the item priority list, when that control is offered."
L["Help.ItemSets.list.bottom"] = "Mueve esta entrada a la última posición de la lista de prioridad de objetos, cuando se ofrezca ese control."
-- en: "Remove this entry from the list. In a draft editor this remains pending until Apply, and Discard abandons the row edit. Undo is available where the containing editor provides draft history. This differs from permanently deleting the entire set after confirmation."
L["Help.ItemSets.list.delete"] = "Quita esta entrada de la lista. En un editor con borrador, queda pendiente hasta Aplicar, y Descartar abandona la edición de la fila. Deshacer está disponible cuando el editor que la contiene ofrece historial del borrador. Esto es distinto de borrar permanentemente todo el conjunto tras confirmarlo."
-- en: "Default rotation view"
L["Default rotation view"] = "Vista de rotación predeterminada"
-- en: "Choose Diagram or List as the starting rotation view. This profile preference applies when opening a rotation; changing the view inside the editor does not change this setting. Cooldowns always use a scrolling grid."
L["Choose Diagram or List as the starting rotation view. This profile preference applies when opening a rotation; changing the view inside the editor does not change this setting. Cooldowns always use a scrolling grid."] = "Elige Diagrama o Lista como vista inicial de la rotación. Esta preferencia del perfil se aplica al abrir una rotación; cambiar la vista dentro del editor no cambia este ajuste. Los tiempos de reutilización siempre usan una cuadrícula desplazable."
-- en: "Reset diagram zoom to 100%. Scroll to zoom; middle-click to reset. Drag empty space to pan."
L["Reset diagram zoom to 100%. Scroll to zoom; middle-click to reset. Drag empty space to pan."] = "Restablece el zoom del diagrama al 100%. Usa la rueda para hacer zoom; clic central para restablecer. Arrastra el espacio vacío para desplazarte."
-- en: "Move this and following entries"
L["Move this and following entries"] = "Mover esta entrada y las siguientes"
-- en: "Drag one entry; Ctrl-drag moves it and all following siblings."
L["Drag one entry; Ctrl-drag moves it and all following siblings."] = "Arrastra una entrada; Ctrl+arrastrar la mueve junto con todos los hermanos siguientes."
-- en: "%d cards"
L["%d cards"] = "%d tarjetas"
-- en: " (%d hidden)"
L[" (%d hidden)"] = " (%d ocultas)"
-- en: "Click to fold or unfold this branch arm. Other cards and conditions are unchanged."
L["Click to fold or unfold this branch arm. Other cards and conditions are unchanged."] = "Haz clic para plegar o desplegar este brazo de la rama. Las demás tarjetas y condiciones no cambian."
-- en: "%s totem {{!is|is not}} active"
L["%s totem {{!is|is not}} active"] = "el tótem de %s {{!está|no está}} activo"
-- en: "%s {{!are|are not}} %s"
L["%s {{!are|are not}} %s"] = "%s {{!eres|no eres}} %s"
-- en: "%s {{!are|are not}} PVP flagged"
L["%s {{!are|are not}} PVP flagged"] = "%s {{!estás|no estás}} marcado para JcJ"
-- en: "%s {{!are|are not}} a %s"
L["%s {{!are|are not}} a %s"] = "%s {{!eres|no eres}} %s"
-- en: "%s {{!are|are not}} currently casting"
L["%s {{!are|are not}} currently casting"] = "%s {{!estás|no estás}} lanzando un hechizo"
-- en: "%s {{!are|are not}} currently casting %s"
L["%s {{!are|are not}} currently casting %s"] = "%s {{!estás|no estás}} lanzando %s"
-- en: "{unit} {{!are|are not}} currently casting {spell}"
L["{unit} {{!are|are not}} currently casting {spell}"] = "{unit} {{!estás|no estás}} lanzando {spell}"
-- en: "%s {{!are|are not}} currently channeling"
L["%s {{!are|are not}} currently channeling"] = "%s {{!estás|no estás}} canalizando"
-- en: "%s {{!are|are not}} currently channeling %s"
L["%s {{!are|are not}} currently channeling %s"] = "%s {{!estás|no estás}} canalizando %s"
-- en: "{unit} {{!are|are not}} currently channeling {spell}"
L["{unit} {{!are|are not}} currently channeling {spell}"] = "{unit} {{!estás|no estás}} canalizando {spell}"
-- en: "%s {{!are|are not}} in combat"
L["%s {{!are|are not}} in combat"] = "%s {{!estás|no estás}} en combate"
-- en: "%s {{!has|does not have}} %s"
L["%s {{!has|does not have}} %s"] = "%s {{!tiene|no tiene}} %s"
-- en: "%s {{!has|does not have}} a %s debuff"
L["%s {{!has|does not have}} a %s debuff"] = "%s {{!tiene|no tiene}} un perjuicio de %s"
-- en: "%s {{!has|does not have}} a stealable buff"
L["%s {{!has|does not have}} a stealable buff"] = "%s {{!tiene|no tiene}} un beneficio robable"
-- en: "%s {{!have|do not have}} %s"
L["%s {{!have|do not have}} %s"] = "%s {{!tienes|no tienes}} %s"
-- en: "%s {{!have|do not have}} %s where %s"
L["%s {{!have|do not have}} %s where %s"] = "%s {{!tienes|no tienes}} %s donde %s"
-- en: "%s {{!have|do not have}} a %s debuff"
L["%s {{!have|do not have}} a %s debuff"] = "%s {{!tienes|no tienes}} un perjuicio de %s"
-- en: "%s {{!is|is not}} %s"
L["%s {{!is|is not}} %s"] = "%s {{!es|no es}} %s"
-- en: "%s {{!is|is not}} PVP flagged"
L["%s {{!is|is not}} PVP flagged"] = "%s {{!está|no está}} marcado para JcJ"
-- en: "%s {{!is|is not}} a %s"
L["%s {{!is|is not}} a %s"] = "%s {{!es|no es}} %s"
-- en: "%s {{!is|is not}} active"
L["%s {{!is|is not}} active"] = "%s {{!está|no está}} activo"
